package com.example.nailsalon.config;
import com.example.nailsalon.entity.*; import com.example.nailsalon.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer { @Bean CommandLineRunner init(UserRepository users,ClientRepository clients,MasterRepository masters,NailServiceRepository services,MaterialRepository materials,AppointmentRepository appointments,PaymentRepository payments,ReviewRepository reviews,PasswordEncoder enc){return args->{if(users.count()==0){users.save(new User("admin",enc.encode("admin123"),"ADMIN"));users.save(new User("user",enc.encode("user123"),"USER"));} if(clients.count()==0){Client c=new Client();c.setName("Анна Иванова");c.setPhone("+79990001122");c.setEmail("anna@example.com");clients.save(c);} if(masters.count()==0){Master m=new Master();m.setName("Мария");m.setSpecialization("Маникюр");m.setExperienceYears(5);masters.save(m);} if(services.count()==0){NailService s=new NailService();s.setName("Классический маникюр");s.setDescription("Маникюр с покрытием");s.setPrice(1500);s.setDurationMinutes(90);services.save(s);} if(materials.count()==0){Material m=new Material();m.setName("Гель-лак");m.setQuantity(20);m.setPrice(500);materials.save(m);} };} }
